func (h *hnsw) SearchByVector(ctx context.Context, vector []float32, k int, allowList helpers.AllowList) ([]uint64, []float32, error) {
    flatSearchCutoff := int(atomic.LoadInt64(&h.flatSearchCutoff))
    if allowList != nil && !h.forbidFlat && allowList.Len() < flatSearchCutoff {
        helpers.AnnotateSlowQueryLog(ctx, "hnsw_flat_search", true)
        return h.flatSearch(ctx, vector, k, h.searchTimeEF(k), allowList)
    }

